-- Pinned to 3xjn/prism@1974a8b77f3eeaa05963ac26abc557b16fd6ad8e.
-- Prism/React/compiler licenses are included in ThirdPartyNotices.luau below.
-- loadstring(game:HttpGet("https://raw.githubusercontent.com/3xjn/qos-mm2/main/prism.lua"))()
-- returns React, ReactRoblox, Prism, Package, Cleanup
return (function()
local makeRuntime=(function()
-- A private ModuleScript-shaped tree for the pinned, unmodified Prism sources.
-- No executor filesystem API, external UI download, or global require override.
return function(manifest)
    local environment = getfenv()
    local nativeRequire = require
    local nodes, sources, values, loading = {}, {}, {}, {}
    local nilValue = {}
    local moduleGlobals = { __DEV__ = false, __PROFILE__ = false }
    local methods = {}
    function methods:GetFullName()
        return self.Parent and (self.Parent:GetFullName() .. "." .. self.Name) or self.Name
    end
    function methods:FindFirstChild(name, recursive)
        local child = self._children[name]
        if child then return child end
        if recursive then
            for _, item in pairs(self._children) do
                local found = item:FindFirstChild(name, true)
                if found then return found end
            end
        end
        return nil
    end
    function methods:WaitForChild(name)
        local child = self:FindFirstChild(name)
        assert(child, "Bundled Prism dependency missing: " .. self:GetFullName() .. "." .. name)
        return child
    end
    function methods:IsA(className)
        return className == self.ClassName or className == "Instance"
    end
    function methods:FindFirstAncestorWhichIsA(className)
        local current = self.Parent
        while current do
            if current:IsA(className) then return current end
            current = current.Parent
        end
        return nil
    end
    methods.FindFirstAncestorOfClass = methods.FindFirstAncestorWhichIsA
    function methods:FindFirstAncestor(name)
        local current = self.Parent
        while current do
            if current.Name == name then return current end
            current = current.Parent
        end
        return nil
    end
    function methods:GetDescendants()
        local descendants = {}
        for _, child in pairs(self._children) do
            table.insert(descendants, child)
            for _, item in ipairs(child:GetDescendants()) do table.insert(descendants, item) end
        end
        return descendants
    end
    function methods:IsDescendantOf(ancestor)
        local current = self.Parent
        while current do
            if current == ancestor then return true end
            current = current.Parent
        end
        return false
    end
    function methods:GetChildren()
        local children = {}
        for _, child in pairs(self._children) do table.insert(children, child) end
        return children
    end
    function methods:Destroy()
        if self._destroyed then return end
        self._destroyed = true
        for _, child in pairs(self._children) do child:Destroy() end
        sources[self] = nil
        values[self] = nil
        loading[self] = nil
    end
    local metatable = {
        __index = function(node, key) return methods[key] or node._children[key] end,
        __tostring = function(node) return node:GetFullName() end,
    }
    for id, item in ipairs(manifest) do
        local node = setmetatable({Name=item.name, ClassName=item.source and "ModuleScript" or "Folder", _children={}}, metatable)
        nodes[id] = node
        if item.source then sources[node] = item.source end
        if item.parent then
            node.Parent = assert(nodes[item.parent], "Bundled Prism parent missing")
            node.Parent._children[node.Name] = node
        end
    end
    local function import(module)
        if type(module) ~= "table" or not sources[module] then return nativeRequire(module) end
        if values[module] == nilValue then return nil end
        if values[module] ~= nil then return values[module] end
        assert(not loading[module], "Circular bundled dependency: " .. module:GetFullName())
        local chunk, message = loadstring(sources[module], "=" .. module:GetFullName())
        assert(chunk, message)
        setfenv(chunk, setmetatable({script=module, require=import, _G=moduleGlobals}, {__index=environment}))
        loading[module] = true
        local ok, value = xpcall(chunk, function(message)
            return tostring(message) .. "\n" .. debug.traceback()
        end)
        loading[module] = nil
        if not ok then error(value, 0) end
        values[module] = value == nil and nilValue or value
        return value
    end
    local root = assert(nodes[1])
    local runtime = {Package=root}
    runtime.React = import(root:WaitForChild("React"))
    runtime.ReactRoblox = import(root:WaitForChild("ReactRoblox"))
    runtime.Prism = import(root)
    assert(type(runtime.React.createElement) == "function", "React.createElement unavailable")
    assert(type(runtime.ReactRoblox.createRoot) == "function", "ReactRoblox.createRoot unavailable")
    assert(type(runtime.Prism.DEFAULT_DARK_THEME) == "table", "Prism theme unavailable")
    runtime.Cleanup = function() root:Destroy() end
    return runtime
end

end)()
